using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using XingHai.LE01.Core;
static class Program {
 static readonly JsonSerializerOptions Json=new JsonSerializerOptions {IncludeFields=true,WriteIndented=true};
 static TerrainDocument Circle(){var d=new TerrainDocument{Id="LE04-baseline24",BaseHeight=-48,ActiveQuantum=2};var c=new TerrainCommand{Mode=BrushMode.Extend,Radius=12,Quantum=2};c.Path.Add(new Point2(0,0));var r=TerrainKernel.Apply(d,c);if(r.Rejected)throw new Exception(r.Message);return TerrainGenerators.UpgradeToV3(r.Document);}
 static TerrainDocument Flat(){var d=new TerrainDocument{Id="LE04-flat",BaseHeight=-16,GeneratorVersion="le01.2"};for(int z=-32;z<32;z+=4)for(int x=-32;x<32;x+=4)d.Cells.Add(new TerrainCell{X=x,Z=z,Size=4,Top=0,PlaneId="p0"});return d;}
 static string Hash(TerrainBuild b){using(var s=new MemoryStream())using(var w=new BinaryWriter(s,Encoding.UTF8,true)){foreach(var c in b.Chunks){w.Write(c.Id);foreach(var a in new[]{c.Vertices,c.Normals,c.UV}){w.Write(a.Length);foreach(var v in a)w.Write(v);}foreach(var t in c.Triangles)w.Write(t);foreach(var a in new[]{c.TriangleGroupIds,c.TriangleChildIds,c.TriangleBoundaryKeys})foreach(var v in a)w.Write(v??"");}w.Flush();return Convert.ToHexString(SHA256.HashData(s.ToArray()));}}
 static double P95(List<double> v){v.Sort();return v[(int)Math.Ceiling(v.Count*.95)-1];}
 static void Main(){string root=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../../"));Directory.CreateDirectory(Path.Combine(root,"reports"));Directory.CreateDirectory(Path.Combine(root,"qa/fixtures"));var docs=new List<TerrainDocument>{Circle(),Flat()};var cliff=Circle();cliff.Id="LE04-cliff";foreach(var c in cliff.Cells)if(c.X>0)c.Top=64;docs.Add(cliff);var cross=Flat();cross.Id="LE04-cross-negative";foreach(var c in cross.Cells){c.X-=48;c.Z-=64;}docs.Add(cross);var rows=new List<object>();foreach(var d in docs){File.WriteAllText(Path.Combine(root,"qa/fixtures",d.Id+".json"),JsonSerializer.Serialize(d,Json));var watch=Stopwatch.StartNew();var cold=TerrainCompiler.Build(d);double coldMs=watch.Elapsed.TotalMilliseconds;var full=new List<double>();var alloc=new List<long>();var edit=new List<double>();var partial=new List<double>();var cmd=new TerrainCommand{Mode=BrushMode.Raise,Radius=1.5f,Quantum=4,TargetHeight=4,Strength=.25f,Falloff=1};cmd.Path.Add(new Point2(.5f,0));for(int i=-5;i<20;i++){long b=GC.GetAllocatedBytesForCurrentThread();watch.Restart();var r=TerrainKernel.Apply(d,cmd);double em=watch.Elapsed.TotalMilliseconds;if(r.Rejected)throw new Exception(r.Message);watch.Restart();TerrainCompiler.Build(d);double fm=watch.Elapsed.TotalMilliseconds;watch.Restart();TerrainCompiler.Build(r.Document,r.DirtyBounds);double pm=watch.Elapsed.TotalMilliseconds;if(i>=0){full.Add(fm);edit.Add(em);partial.Add(pm);alloc.Add(GC.GetAllocatedBytesForCurrentThread()-b);}}int top=0;foreach(var c in cold.Chunks)for(int t=0;t<c.Triangles.Length;t+=3)if(c.Normals[c.Triangles[t]*3+1]>.99f)top++;rows.Add(new {id=d.Id,leaves=d.Cells.Count,author=TerrainQueries.ContentHash(d),mesh=Hash(cold),topTriangles=top,triangles=cold.Chunks.Sum(c=>c.Triangles.Length/3),chunks=cold.Chunks.Count,coldMs,fullP95Ms=P95(full),kernelP95Ms=P95(edit),partialP95Ms=P95(partial),maxAllocatedBytes=alloc.Max(),scope="Core only; actual current-thread allocated bytes for Kernel+full+partial; excludes Unity upload, Collider, GPU and SceneView"});}File.WriteAllText(Path.Combine(root,"reports/baseline-core.json"),JsonSerializer.Serialize(rows,Json));Console.WriteLine(JsonSerializer.Serialize(rows,Json));}
}
